#include <iostream>
#include <queue>
#include <vector>
#include <algorithm>
using namespace std;

struct Item {
    int weight, profit;
    double ratio;
};

struct Node {
    int level, profit, weight;
    double bound;
};

bool cmpRatio(Item a, Item b) {
    return a.ratio > b.ratio;
}

// Calculate upper bound using fractional knapsack
double calculateBound(Node u, int n, int W, vector<Item>& items) {
    if (u.weight >= W) return 0;

    double bound = u.profit;
    int totalWeight = u.weight;
    int j = u.level + 1;

    // Greedily add items by ratio
    while (j < n && totalWeight + items[j].weight <= W) {
        totalWeight += items[j].weight;
        bound += items[j].profit;
        j++;
    }

    // Add fraction of next item
    if (j < n) {
        bound += (double)(W - totalWeight) * items[j].ratio;
    }

    return bound;
}

int knapsackBnB(int W, vector<Item>& items, int n) {
    sort(items.begin(), items.end(), cmpRatio);

    queue<Node> Q; // FIFO B&B
    Node u, v;

    // Root node
    u.level = -1; u.profit = 0; u.weight = 0;
    u.bound = calculateBound(u, n, W, items);
    Q.push(u);

    int maxProfit = 0;

    while (!Q.empty()) {
        u = Q.front(); Q.pop();
        if (u.level == n - 1) continue;

        // Include next item
        v.level = u.level + 1;
        v.weight = u.weight + items[v.level].weight;
        v.profit = u.profit + items[v.level].profit;

        if (v.weight <= W && v.profit > maxProfit)
            maxProfit = v.profit;

        v.bound = calculateBound(v, n, W, items);
        if (v.bound > maxProfit)
            Q.push(v);

        // Exclude next item
        v.weight = u.weight;
        v.profit = u.profit;
        v.bound = calculateBound(v, n, W, items);
        if (v.bound > maxProfit)
            Q.push(v);
    }

    return maxProfit;
}

int main() {
    int W = 10;
    vector<Item> items = {{2, 40, 20.0}, {3, 50, 16.67}, {5, 100, 20.0}, {7, 135, 19.28}};
    int n = items.size();

    cout << "Maximum Profit: " << knapsackBnB(W, items, n) << endl;
    return 0;
}

