    let queue = [{ level: -1, profit: 0, weight: 0, bound: 0 }];
    queue[0].bound = calculateBound(queue[0], n, W, items);
    let maxProfit = 0;

    while (queue.length > 0) {
        let u = queue.shift();
        if (u.level === n - 1) continue;
        let vLevel = u.level + 1;
        // Include
        let include = { level: vLevel, profit: u.profit + items[vLevel].profit,
                        weight: u.weight + items[vLevel].weight, bound: 0 };
        if (include.weight <= W && include.profit > maxProfit)
            maxProfit = include.profit;
        include.bound = calculateBound(include, n, W, items);
        if (include.bound > maxProfit) queue.push(include);
        // Exclude
        let exclude = { level: vLevel, profit: u.profit, weight: u.weight, bound: 0 };
        exclude.bound = calculateBound(exclude, n, W, items);
        if (exclude.bound > maxProfit) queue.push(exclude);
    }
    return maxProfit;
}

