Node queue[10000];
int front = 0, rear = 0;
void enqueue(Node n) { queue[rear++] = n; }
Node dequeue() { return queue[front++]; }
int isEmpty() { return front == rear; }

int cmp(const void *a, const void *b) {
    double diff = ((Item*)b)->ratio - ((Item*)a)->ratio;
    return (diff > 0) - (diff < 0);
}

double calcBound(Node u, int n, int W, Item items[]) {
    if (u.weight >= W) return 0;
    double bound = u.profit;
    int tw = u.weight, j = u.level + 1;
    while (j < n && tw + items[j].weight <= W) {
        tw += items[j].weight;
        bound += items[j].profit;
        j++;
    }
    if (j < n) bound += (double)(W - tw) * items[j].ratio;
    return bound;
}

int knapsackBnB(int W, Item items[], int n) {
    qsort(items, n, sizeof(Item), cmp);
    Node u = {-1, 0, 0, 0};
    u.bound = calcBound(u, n, W, items);
    enqueue(u);
    int maxProfit = 0;
    while (!isEmpty()) {
        u = dequeue();
        if (u.level == n - 1) continue;
        Node v;
        v.level = u.level + 1;
        v.weight = u.weight + items[v.level].weight;
        v.profit = u.profit + items[v.level].profit;
        if (v.weight <= W && v.profit > maxProfit) maxProfit = v.profit;
        v.bound = calcBound(v, n, W, items);
        if (v.bound > maxProfit) enqueue(v);
        v.weight = u.weight; v.profit = u.profit;
        v.bound = calcBound(v, n, W, items);
        if (v.bound > maxProfit) enqueue(v);
    }
    return maxProfit;
}

