#include <iostream>
#include <vector>
#include <queue>
#include <climits>
using namespace std;

const int INF = INT_MAX;
const int N = 4;

struct Node {
    int cost;                    // Lower bound
    int vertex;                  // Current city
    int level;                   // Number of cities visited
    vector<vector<int>> matrix;  // Reduced cost matrix
    vector<int> path;
};

struct CompareNode {
    bool operator()(const Node& a, const Node& b) {
        return a.cost > b.cost;
    }
};

// Reduce matrix and return reduction cost
int reduceMatrix(vector<vector<int>>& matrix, int n) {
    int reductionCost = 0;

    // Row reduction
    for (int i = 0; i < n; i++) {
        int rowMin = INF;
        for (int j = 0; j < n; j++)
            if (matrix[i][j] < rowMin) rowMin = matrix[i][j];
        if (rowMin != INF && rowMin > 0) {
            reductionCost += rowMin;
            for (int j = 0; j < n; j++)
                if (matrix[i][j] != INF) matrix[i][j] -= rowMin;
        }
    }

    // Column reduction
    for (int j = 0; j < n; j++) {
        int colMin = INF;
        for (int i = 0; i < n; i++)
            if (matrix[i][j] < colMin) colMin = matrix[i][j];
        if (colMin != INF && colMin > 0) {
            reductionCost += colMin;
            for (int i = 0; i < n; i++)
                if (matrix[i][j] != INF) matrix[i][j] -= colMin;
        }
    }
    return reductionCost;
}

int tspBnB(vector<vector<int>>& costMatrix, int n) {
    priority_queue<Node, vector<Node>, CompareNode> pq;

    // Create root node
    Node root;
    root.matrix = costMatrix;
    root.cost = reduceMatrix(root.matrix, n);
    root.vertex = 0;
    root.level = 0;
    root.path.push_back(0);
    pq.push(root);

    int bestCost = INF;

    while (!pq.empty()) {
        Node current = pq.top(); pq.pop();

        if (current.cost >= bestCost) continue;

        if (current.level == n - 1) {
            bestCost = min(bestCost, current.cost);
            continue;
        }

        for (int j = 0; j < n; j++) {
            if (current.matrix[current.vertex][j] == INF) continue;

            Node child;
            child.matrix = current.matrix;
            child.level = current.level + 1;
            child.vertex = j;
            child.path = current.path;
            child.path.push_back(j);

            // Cost including edge (current.vertex, j)
            child.cost = current.cost + current.matrix[current.vertex][j];

            // Set row and column to INF
            for (int k = 0; k < n; k++) {
                child.matrix[current.vertex][k] = INF;
                child.matrix[k][j] = INF;
            }
            child.matrix[j][0] = INF;

            child.cost += reduceMatrix(child.matrix, n);

            if (child.cost < bestCost)
                pq.push(child);
        }
    }
    return bestCost;
}

int main() {
    vector<vector<int>> cost = {
        {INF, 10, 15, 20},
        {10, INF, 35, 25},
        {15, 35, INF, 30},
        {20, 25, 30, INF}
    };
    cout << "Minimum TSP cost: " << tspBnB(cost, N) << endl;
    return 0;
}

